package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.List;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathIntrospector;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyPointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for PropertyPointer.getLength()
 */
public class PropertyPointer_getLength_TriageGen0Test {

    /**
     * Since PropertyPointer is an abstract class (implied by abstract methods),
     * we use a Mockito spy on a concrete implementation or a mock of the class
     * to control the behavior of getBaseValue().
     * 
     * Note: getBaseValue() is likely a protected method in the hierarchy.
     */
    @Test
    public void testGetLength_WithList() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        // We mock the PropertyPointer class itself to control getBaseValue()
        PropertyPointer pointer = mock(PropertyPointer.class, Mockito.CALLS_REAL_METHODS);

        List<String> testList = Arrays.asList("a", "b", "c");

        // We must simulate the internal call getBaseValue() returning the list
        // Since getBaseValue is not in the provided signature but used in the method,
        // we assume it's accessible to the subclass/spy.
        when(pointer.getImmediateNode()).thenReturn(testList); 
        // In many JXPath implementations, getBaseValue() returns the object at the current pointer
        // For the sake of this test, we assume the logic flows through getBaseValue()
        // If getBaseValue() is protected, we use a spy to stub it.

        // Re-mocking using a concrete subclass approach for better control if getBaseValue is private/protected
        PropertyPointer spyPointer = spy(new TestPropertyPointer(mockParent));
        doReturn(testList).when(spyPointer).getBaseValue();

        // Act
        int length = spyPointer.getLength();

        // Assert
        assertEquals(3, length);
    }

    @Test
    public void testGetLength_WithArray() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        String[] testArray = {"one", "two"};

        PropertyPointer spyPointer = spy(new TestPropertyPointer(mockParent));
        doReturn(testArray).when(spyPointer).getBaseValue();

        // Act
        int length = spyPointer.getLength();

        // Assert
        assertEquals(2, length);
    }

    @Test
    public void testGetLength_WithEmptyList() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        List<Integer> emptyList = Arrays.asList();

        PropertyPointer spyPointer = spy(new TestPropertyPointer(mockParent));
        doReturn(emptyList).when(spyPointer).getBaseValue();

        // Act
        int length = spyPointer.getLength();

        // Assert
        assertEquals(0, length);
    }

    @Test(expected = Exception.class)
    public void testGetLength_WithNull() {
        // Arrange
        NodePointer mockParent = mock(NodePointer.class);
        PropertyPointer spyPointer = spy(new TestPropertyPointer(mockParent));
        doReturn(null).when(spyPointer).getBaseValue();

        // Act
        spyPointer.getLength();

        // Assert: Expect exception from ValueUtils.getLength(null)
    }

    /**
     * Concrete implementation of PropertyPointer for testing purposes
     * to allow overriding/stubbing protected methods.
     */
    private static class TestPropertyPointer extends PropertyPointer {
        public TestPropertyPointer(NodePointer parent) {
            super(parent);
        }

        @Override
        public String getPropertyName() { return "test"; }
        @Override
        public void setPropertyName(String propertyName) {}
        @Override
        public int getPropertyCount() { return 0; }
        @Override
        public String[] getPropertyNames() { return new String[0]; }
        @Override
        protected boolean isActualProperty() { return true; }

        // Mocking the internal method used by getLength()
        public Object getBaseValue() {
            return null; 
        }
    }
}
